root=Path.cwd();out=root/'revision_coherencia/entregables';out.mkdir(exist_ok=True)
p=next((root/'00_Cuestionario/V1').glob('Matriz*.xlsx'));w=load_workbook(p,data_only=True);sh=w['Hallazgos del instrumento'];obs=[]
for rn,row in enumerate(sh.values,1):
 if not isinstance(row[0],(int,float)):continue
 priority=str(row[6]);obs.append(dict(id=int(row[0]),location=str(row[1]),finding=str(row[2]),impact=str(row[3]),indicators=str(row[4]),action=str(row[5]),priority='No aplica' if priority=='Resuelto' else priority,status='Resuelto en fuente' if priority=='Resuelto' else 'Pendiente',origin='Matriz V07: hallazgo documentado',source=p.name+' | Hallazgos del instrumento | fila '+str(rn)))
