b=xlsxwriter.Workbook(str(out/'Observaciones_formularios_ENUS_V07.xlsx'));wrap=b.add_format({'font_name':'Arial','font_size':10,'text_wrap':True,'valign':'top'});hdr=b.add_format({'font_name':'Arial','bold':True,'bg_color':'#1F4E79','font_color':'white','text_wrap':True});s=b.add_worksheet('Observaciones');headers=['ID','Origen','Ubicación / módulo','Observación','Impacto','Indicadores afectados','Acción propuesta','Prioridad','Estado','Fuente y ubicación','Responsable','Fecha compromiso','Respuesta del equipo','Evidencia de cierre'];s.write_row(0,0,headers,hdr)
for i,o in enumerate(obs,1):s.write_row(i,0,[o['id'],o['origin'],o['location'],o['finding'],o['impact'],o['indicators'],o['action'],o['priority'],o['status'],o['source'],'','','',''],wrap);s.set_row(i,115)
s.freeze_panes(1,3);s.autofilter(0,0,len(obs),13);s.set_column(0,0,6);s.set_column(1,2,30);s.set_column(3,4,55);s.set_column(5,5,30);s.set_column(6,6,60);s.set_column(7,8,22);s.set_column(9,9,45);s.set_column(10,13,28);s.data_validation(1,8,len(obs),8,{'validate':'list','source':['Pendiente','Requiere decisión','En revisión','En ajuste','Resuelto en fuente','Cerrado']});s.data_validation(1,7,len(obs),7,{'validate':'list','source':['Alta','Media','Baja','No aplica']})
s.set_landscape();s.fit_to_pages(1,0);s.repeat_rows(0);s.hide_gridlines(2)
