r.write(1,0,'Total de observaciones');r.write_formula(1,1,'=COUNTA(Observaciones!A2:A27)',None,len(obs))
for i,label in enumerate(['Alta','Media','Baja','No aplica'],2):r.write(i,0,label);r.write_formula(i,1,f'=COUNTIF(Observaciones!H2:H27,A{i+1})',None,counts[label])
